import{_ as a,o as l,c as i,ae as o}from"./chunks/framework.BX6FPmO9.js";const k=JSON.parse('{"title":"UI Review Checklist v1（定版）","description":"","frontmatter":{},"headers":[],"relativePath":"product/ui-review-checklist.md","filePath":"product/ui-review-checklist.md"}'),r={name:"product/ui-review-checklist.md"};function t(c,e,d,s,n,h){return l(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="ui-review-checklist-v1-定版" tabindex="-1">UI Review Checklist v1（定版） <a class="header-anchor" href="#ui-review-checklist-v1-定版" aria-label="Permalink to &quot;UI Review Checklist v1（定版）&quot;">​</a></h1><blockquote><p>定版日：2026-07-08 · 出處：<a href="./visual-quality-plan.html">visual-quality-plan.md</a> §2.A 直接採用八項的萃取定版 素材來源：<a href="https://github.com/Leonxlnx/taste-skill" target="_blank" rel="noreferrer">Leonxlnx/taste-skill</a> <code>design-taste-frontend</code> v2（已在地化改寫；上游更新追蹤見 visual-quality-plan §0） 適用：所有 UI PR。先標注 surface（marketing / product / data / developer），通用段全查，加驗段依 surface 查。</p></blockquote><h2 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h2><ol><li>PR 描述標注觸及頁面的 surface tag。</li><li>逐項自查通用段；命中加驗段的 surface 再查對應段。</li><li>任一項無法誠實勾選 → 未完成，不出貨（可標注豁免理由供 review 討論）。</li></ol><hr><h2 id="通用-全-surface" tabindex="-1">通用（全 surface） <a class="header-anchor" href="#通用-全-surface" aria-label="Permalink to &quot;通用（全 surface）&quot;">​</a></h2><h3 id="決策可追溯" tabindex="-1">決策可追溯 <a class="header-anchor" href="#決策可追溯" aria-label="Permalink to &quot;決策可追溯&quot;">​</a></h3><ul><li>[ ] 無寫死色值／字級／間距——一律經 SDK token（<code>var(--x)</code> 或 Tailwind 語意 utility）</li><li>[ ] 新視覺決策有出處（brief、PALETTE.md、或本次 PR 說明），不是「AI 給的預設」</li></ul><h3 id="一致性三-lock" tabindex="-1">一致性三 Lock <a class="header-anchor" href="#一致性三-lock" aria-label="Permalink to &quot;一致性三 Lock&quot;">​</a></h3><ul><li>[ ] Page Theme Lock：頁面單一主題，section 不反轉明暗</li><li>[ ] Color Consistency Lock：accent 全頁一致，不中途換色</li><li>[ ] Shape Consistency Lock：單一圓角系統（沿 <code>radius.base</code> 派生）</li></ul><h3 id="對比與可及性" tabindex="-1">對比與可及性 <a class="header-anchor" href="#對比與可及性" aria-label="Permalink to &quot;對比與可及性&quot;">​</a></h3><ul><li>[ ] Button／CTA 對比 ≥ WCAG AA（4.5:1；大字 18px+ 為 3:1）</li><li>[ ] Form：input、placeholder、focus ring、error text 全過 AA；label 在上、error 在下、不以 placeholder 代 label</li><li>[ ] 照片底按鈕有 scrim／backdrop／描邊</li><li>[ ] 焦點環可見；鍵盤可達</li></ul><h3 id="四態完整性" tabindex="-1">四態完整性 <a class="header-anchor" href="#四態完整性" aria-label="Permalink to &quot;四態完整性&quot;">​</a></h3><ul><li>[ ] Loading：形狀吻合的 skeleton（SDK ux <code>Skeleton</code>），不用泛用轉圈</li><li>[ ] Empty：有引導行動（SDK ux <code>EmptyState</code>；AI 降級沿用並保留使用者輸入）</li><li>[ ] Error：表單 inline、transient 才用 toast</li><li>[ ] Tactile：<code>:active</code> 有回饋（<code>scale-[0.98]</code> 或 <code>-translate-y-[1px]</code>）</li></ul><h3 id="反-fake-ui" tabindex="-1">反 fake-UI <a class="header-anchor" href="#反-fake-ui" aria-label="Permalink to &quot;反 fake-UI&quot;">​</a></h3><ul><li>[ ] 無 div 拼裝假截圖／假產品預覽</li><li>[ ] 精確數字有真實來源，否則標注 mock（禁無來源的「92%」「4.1×」）</li><li>[ ] 無假人名、蛋形 avatar、虛構 logo 牆；demo 資料一律可辨識為 mock</li></ul><h3 id="動效紀律" tabindex="-1">動效紀律 <a class="header-anchor" href="#動效紀律" aria-label="Permalink to &quot;動效紀律&quot;">​</a></h3><ul><li>[ ] 每個動畫能一句話說出目的（層級／敘事／回饋／狀態轉換）；「看起來酷」不算</li><li>[ ] 尊重 <code>prefers-reduced-motion</code></li><li>[ ] 禁 <code>window.addEventListener(&#39;scroll&#39;)</code>；動效時長／easing 用 SDK motion tokens</li><li>[ ] marquee 每頁 ≤ 1</li></ul><h3 id="中文排版與文案" tabindex="-1">中文排版與文案 <a class="header-anchor" href="#中文排版與文案" aria-label="Permalink to &quot;中文排版與文案&quot;">​</a></h3><ul><li>[ ] 全形標點一致；中文內容不混英文 em-dash（<code>—</code> 僅限中文破折號「——」語法）</li><li>[ ] body 行長 ≤ 42 全形字（英文 ≤ 65ch）</li><li>[ ] 文案自審完成：刪 AI 腔 filler——「賦能」「極致」「無縫」「重新定義」「一站式」「開箱即用」濫用、「Elevate／Seamless／Unleash」</li><li>[ ] 一頁一種語氣；引用 ≤ 3 行且署名含姓名＋職稱</li></ul><h3 id="工程收尾" tabindex="-1">工程收尾 <a class="header-anchor" href="#工程收尾" aria-label="Permalink to &quot;工程收尾&quot;">​</a></h3><ul><li>[ ] 多欄版面逐段明示 <code>&lt; 768px</code> 摺疊行為</li><li>[ ] <code>min-h-[100dvh]</code>，不用 <code>h-screen</code></li><li>[ ] light／dark 兩模式皆目視檢查</li><li>[ ] 版面家族每頁不重複（同構 section 出現第 2 次即重排）</li></ul><hr><h2 id="marketing-developer-surface-加驗" tabindex="-1">marketing / developer surface 加驗 <a class="header-anchor" href="#marketing-developer-surface-加驗" aria-label="Permalink to &quot;marketing / developer surface 加驗&quot;">​</a></h2><ul><li>[ ] 首屏：標題 ≤ 2 行、說明 ≤ 40 全形字（英文 ≤ 20 words）、CTA 免捲動可見</li><li>[ ] hero 頂部 padding ≤ 6rem；hero 內文字元素 ≤ 4（eyebrow 擇一、標題、說明、CTA 組）</li><li>[ ] uppercase 小標（eyebrow）每 3 個 section ≤ 1</li><li>[ ] 左右交錯（zigzag）≤ 連續 2 段</li><li>[ ] CTA 語意不重複：同意圖同標籤（「聯絡我們」不再變體）</li><li>[ ] logo 牆位於 hero 下方、只放 logo、用真實 SVG 或標注 mock</li><li>[ ] 長清單（&gt; 5 項）換元件呈現：分群／tabs／卡片格，不加長清單</li></ul><h2 id="data-surface-加驗-insights-dashboard-api-explorer" tabindex="-1">data surface 加驗（insights / dashboard / API explorer） <a class="header-anchor" href="#data-surface-加驗-insights-dashboard-api-explorer" aria-label="Permalink to &quot;data surface 加驗（insights / dashboard / API explorer）&quot;">​</a></h2><ul><li>[ ] 數字一律 <code>font-mono</code></li><li>[ ] 分隔用 1px 線或留白，不堆疊卡片框</li><li>[ ] 長資料換虛擬列表／分頁，不無限加長</li><li>[ ] 密度提高時仍保留 focus 與 hover 狀態可辨</li></ul><hr><h2 id="改版-redesign-流程約束" tabindex="-1">改版（redesign）流程約束 <a class="header-anchor" href="#改版-redesign-流程約束" aria-label="Permalink to &quot;改版（redesign）流程約束&quot;">​</a></h2><p>動排版前先 audit 並記錄：使用中 token／寫死值清單、layout family 重複處、四態缺漏、要保留與淘汰的 pattern。改善順序固定：<strong>字體 → 間距節奏 → 色彩校準 → 動效 → 關鍵結構重組</strong>，滿足即停，不越級動結構。</p><hr><p><em>變更本檔需同步 <a href="./visual-quality-plan.html">visual-quality-plan.md</a> §8 決策記錄。D2（data surface 用 <code>p-section-dense</code>／<code>gap-stack-dense</code> token）與 D3（Design Read 工作流，見 AGENTS.md「UI 產出規則」）已於 2026-07-08 定案生效。</em></p>',32)])])}const p=a(r,[["render",t]]);export{k as __pageData,p as default};
